#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.."&&pwd)";OUT="$7";mkdir -p "$OUT";chmod 700 "$OUT";python3 "$ROOT/scripts/m9/verify_release_chain.py" --m4-material "$1" --m5-material "$2" --m6-material "$3" --m7-material "$4" --m8-material "$5" --m9-material "$6";"$ROOT/deploy/m4/package_verifier_material.sh" "$1" "$OUT/m4-verifier-material.tar.gz";"$ROOT/deploy/m5/package_verifier_material.sh" "$2" "$OUT/m5-verifier-material.tar.gz";"$ROOT/deploy/m6/package_verifier_material.sh" "$3" "$OUT/m6-verifier-material.tar.gz";"$ROOT/deploy/m7/package_verifier_material.sh" "$4" "$OUT/m7-verifier-material.tar.gz";"$ROOT/deploy/m8/package_verifier_material.sh" "$5" "$OUT/m8-verifier-material.tar.gz";"$ROOT/deploy/m9/package_verifier_material.sh" "$6" "$OUT/m9-verifier-material.tar.gz";for f in "$OUT"/*.tar.gz;do ! tar -tzf "$f"|grep -q signing-private.pem||{ echo "FAIL private key $f";exit 2;};done;(cd "$OUT"&&sha256sum *.tar.gz>verifier-chain.sha256);chmod 600 "$OUT/verifier-chain.sha256";echo "PASS: coherent M4-M9 verifier chain packaged at $OUT"
